-- Transactional deletion script generated from tools/match_zero_stock_cascade.csv
-- Backup tables will be created if missing. Review before running.

-- Create backup tables (structure copied from original tables)
CREATE TABLE IF NOT EXISTS deletion_backup_tb_stock (LIKE tb_stock INCLUDING ALL);
CREATE TABLE IF NOT EXISTS deletion_backup_tb_inventaire (LIKE tb_inventaire INCLUDING ALL);
CREATE TABLE IF NOT EXISTS deletion_backup_tb_log_stock (LIKE tb_log_stock INCLUDING ALL);
CREATE TABLE IF NOT EXISTS deletion_backup_tb_prix (LIKE tb_prix INCLUDING ALL);

-- Article 1: GROS POID | Unit: KAPOAKA | idarticle=3205 idunite=4218 codearticle=0180320500
DO $$
BEGIN
  -- Safety pre-check: ensure there are no tb_stock rows with non-zero entries for this codearticle
  IF (SELECT COUNT(*) FROM tb_stock WHERE codearticle='0180320500') > 0 THEN
    RAISE NOTICE 'Skipping deletion for codearticle=0180320500: % rows in tb_stock', (SELECT COUNT(*) FROM tb_stock WHERE codearticle='0180320500');
  ELSE
    -- Backup matching rows before deleting
    INSERT INTO deletion_backup_tb_log_stock SELECT * FROM tb_log_stock WHERE codearticle='0180320500';
    INSERT INTO deletion_backup_tb_inventaire SELECT * FROM tb_inventaire WHERE codearticle='0180320500';
    INSERT INTO deletion_backup_tb_stock SELECT * FROM tb_stock WHERE codearticle='0180320500';
    INSERT INTO deletion_backup_tb_prix SELECT * FROM tb_prix WHERE idarticle=3205 AND idunite=4218;
    -- Perform deletes in safe order: prix -> log_stock -> inventaire -> stock
DELETE FROM tb_log_stock WHERE idmag=1 AND codearticle='0180320500' AND ancien_stock=0 AND nouveau_stock=0 AND type_action='Entrée en stock par inventaire de départ';
DELETE FROM tb_log_stock WHERE idmag=2 AND codearticle='0180320500' AND ancien_stock=0 AND nouveau_stock=0 AND type_action='Entrée en stock par inventaire de départ';
DELETE FROM tb_log_stock WHERE idmag=3 AND codearticle='0180320500' AND ancien_stock=0 AND nouveau_stock=0 AND type_action='Entrée en stock par inventaire de départ';
DELETE FROM tb_inventaire WHERE idmag=1 AND codearticle='0180320500' AND qtinventaire=0;
DELETE FROM tb_inventaire WHERE idmag=2 AND codearticle='0180320500' AND qtinventaire=0;
DELETE FROM tb_inventaire WHERE idmag=3 AND codearticle='0180320500' AND qtinventaire=0;
DELETE FROM tb_stock WHERE idmag=1 AND codearticle='0180320500';
DELETE FROM tb_stock WHERE idmag=2 AND codearticle='0180320500';
DELETE FROM tb_stock WHERE idmag=3 AND codearticle='0180320500';
  END IF;
END$$;

